const payload = $json.body || $json;
function text(value) { return String(value || '').trim(); }
const eventType = text(payload.event_type || payload.event || payload.type).toLowerCase();
const leadEmail = text(payload.lead_email || payload.email || payload.Email || payload.recipient_email).toLowerCase();
const campaignId = text(payload.campaign_id || payload.campaign || payload.campaignId);
const emailId = text(payload.email_id || payload.email_uuid || payload.reply_to_uuid || payload.message_id);
const emailAccount = text(payload.email_account || payload.sender_email || payload.from_email);
const step = Number(payload.step || payload.sequence_step || payload.step_number || 0);
const timestamp = text(payload.timestamp || payload.created_at || payload.event_time) || new Date().toISOString();
const custom = payload.custom_variables || payload.payload || {};
const rowId = text(payload.rayn_row_id || custom.rayn_row_id || payload.metadata?.rayn_row_id);
const replySnippet = text(payload.reply_text || payload.text_body || payload.body || payload.message || payload.email_body).slice(0, 1000);
let kind = 'unknown';
if (eventType.includes('reply')) kind = 'human_reply';
if (eventType.includes('out_of_office') || eventType.includes('out of office')) kind = 'auto_reply';
if (eventType.includes('bounce')) kind = 'bounce';
if (eventType.includes('unsubscribe')) kind = 'unsubscribed';
if (eventType.includes('sent')) kind = 'email_sent';
return [{ json: { event_type: eventType, kind, lead_email: leadEmail, campaign_id: campaignId, email_id: emailId, email_account: emailAccount, step, timestamp, rayn_row_id: rowId, reply_snippet: replySnippet } }];

const event = $('Normalize Instantly Event').first().json;
const row = Array.isArray($json.list) ? $json.list[0] : null;
if (!row || !row.Id) return [];
const patch = {
  Id: row.Id,
  send_provider: 'instantly',
  instantly_last_event_type: event.event_type || event.kind,
  instantly_last_event_at: event.timestamp,
  instantly_email_account: event.email_account,
  instantly_campaign_id: event.campaign_id || row.instantly_campaign_id || '',
  send_last_attempted_at: event.timestamp
};
if (event.kind === 'email_sent') {
  patch.send_status = 'sent';
  if (!event.step || event.step <= 1) {
    patch.sequence_status = 'email_2_scheduled';
    patch.email_1_send_status = 'sent';
    patch.email_1_sent_at = event.timestamp;
    patch.email_1_message_id = event.email_id;
  } else {
    patch.sequence_status = 'completed';
    patch.email_2_send_status = 'sent';
    patch.email_2_sent_at = event.timestamp;
    patch.email_2_message_id = event.email_id;
  }
} else if (event.kind === 'human_reply') {
  patch.sequence_status = 'replied';
  patch.reply_status = 'human_reply';
  patch.reply_type = 'human';
  patch.reply_detected_at = event.timestamp;
  patch.reply_message_id = event.email_id;
  patch.reply_snippet = event.reply_snippet;
  patch.email_2_send_status = 'cancelled';
  patch.followup_suppressed_reason = 'human_reply_to_email_1';
} else if (event.kind === 'auto_reply') {
  patch.reply_status = 'auto_reply';
  patch.reply_type = 'out_of_office';
  patch.reply_detected_at = event.timestamp;
  patch.reply_message_id = event.email_id;
  patch.reply_snippet = event.reply_snippet;
} else if (event.kind === 'bounce') {
  patch.sequence_status = 'suppressed';
  patch.send_status = 'suppressed';
  patch.reply_status = 'bounce';
  patch.reply_type = 'bounce';
  patch.reply_detected_at = event.timestamp;
  patch.reply_message_id = event.email_id;
  patch.unsubscribe_status = 'bounced';
  patch.followup_suppressed_reason = 'instantly_bounce';
} else if (event.kind === 'unsubscribed') {
  patch.sequence_status = 'suppressed';
  patch.send_status = 'suppressed';
  patch.unsubscribe_status = 'unsubscribed';
  patch.followup_suppressed_reason = 'instantly_unsubscribed';
}
return [{ json: patch }];
